settings.custom_liquid:
{% if collection.description != blank %}
  <div class="collection-desc-wrapper">

    <div class="collection-desc-content" id="collectionDesc">
      {{ collection.description }}
    </div>

    <button class="collection-desc-toggle" id="toggleDesc">
      READ MORE
    </button>

  </div>
{% endif %}
<script>
document.addEventListener("DOMContentLoaded", function () {
  const wrapper = document.querySelector(".collection-desc-wrapper");
  const btn = document.getElementById("toggleDesc");

  if (!wrapper || !btn) return;

  btn.addEventListener("click", function () {
    wrapper.classList.toggle("active");

    if (wrapper.classList.contains("active")) {
      btn.innerText = "READ LESS";
    } else {
      btn.innerText = "READ MORE";
    }
  });
});
</script>

<style>
.collection-desc-wrapper {
     max-width: 1400px;
    margin: 0 auto;
    text-align: left;
    position: relative;
    padding: 30px 30px;
}

.collection-desc-content {
  max-height: 120px; /* collapsed height */
  overflow: hidden;
  position: relative;
  transition: max-height 0.4s ease;
}

/* Fade effect */
.collection-desc-content::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 60px;
  background: linear-gradient(to bottom, rgba(255,255,255,0), #fff);
  transition: opacity 0.3s ease;
}

/* Expanded */
.collection-desc-wrapper.active .collection-desc-content {
  max-height: 1000px;
}

.collection-desc-wrapper.active .collection-desc-content::after {
  opacity: 0;
  pointer-events: none;
}

/* Button */
.collection-desc-toggle {
  margin-top: 12px;
  background: none;
  border: none;
  font-weight: 600;
  cursor: pointer;
  border-bottom: 2px solid #000;
  padding-bottom: 2px;
}
@media screen and (max-width: 767px) {
    .collection-desc-wrapper {
        padding: 30px 16px;
    }
}
</style>

{% assign faq_questions = collection.metafields.custom.faq_questions.value %}
{% assign faq_answers = collection.metafields.custom.faq_answers.value %}

{% if faq_questions != blank and faq_questions.size > 0 %}

<div class="collection-faq" id="collection-faq">
  <div class="faq-container">

    <div class="faq-header">
      <h2 class="faq-title">Frequently Asked Questions</h2>
    </div>

    <div class="faq-list">
      {% for question in faq_questions %}
        {% assign answer = faq_answers[forloop.index0] %}
        {% if question != blank and answer != blank %}
          <div class="faq-item">
            <button
              class="faq-question"
              aria-expanded="false"
              aria-controls="faq-answer-{{ forloop.index }}"
              id="faq-btn-{{ forloop.index }}"
            >

              <span class="faq-q-text">{{ question }}</span>
              <span class="faq-icon" aria-hidden="true">
                <svg width="18" height="18" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <line x1="2" y1="9" x2="16" y2="9" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
                  <line class="faq-icon-v" x1="9" y1="2" x2="9" y2="16" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
                </svg>
              </span>
            </button>
            <div
              class="faq-answer"
              id="faq-answer-{{ forloop.index }}"
              role="region"
              aria-labelledby="faq-btn-{{ forloop.index }}"
            >
              <div class="faq-answer-inner">
                <p>{{ answer }}</p>
              </div>
            </div>
          </div>
        {% endif %}
      {% endfor %}
    </div>

  </div>
</div>

<style>
.collection-faq {
  padding: 72px 24px;
  background: #fff;
border-top: 1px solid #afafaf;
}
.faq-container {
  max-width: 820px;
  margin: 0 auto;
}

/* Header */
.faq-header {
  text-align: center;
  margin-bottom: 48px;
}
.faq-label {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #888;
  margin-bottom: 10px;
}
.faq-title {
  font-size: clamp(26px, 4vw, 38px);
  font-weight: 400;
  color: #111;
  margin: 0;
  letter-spacing: -0.02em;
  font-family: Georgia, 'Times New Roman', serif;
}

/* List */
.faq-list {
  border-top: 1px solid #e5e5e5;
}
.faq-item {
  border-bottom: 1px solid #e5e5e5;
}

/* Question button */
.faq-question {
  display: flex;
  align-items: center;
  gap: 18px;
  width: 100%;
  background: none;
  border: none;
  cursor: pointer;
  padding: 22px 0;
  text-align: left;
  color: #111;
}
.faq-question:hover .faq-q-text {
  opacity: 0.7;
}
.faq-q-number {
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: #aaa;
  min-width: 24px;
  font-variant-numeric: tabular-nums;
  transition: color 0.2s;
}
.faq-q-text {
  flex: 1;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.4;
  transition: opacity 0.2s;
}
.faq-icon {
  flex-shrink: 0;
  width: 34px;
  height: 34px;
  border: 1px solid #ddd;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #111;
  transition: background 0.25s, border-color 0.25s;
}
.faq-icon-v {
  transition: transform 0.3s ease, opacity 0.3s ease;
  transform-origin: center;
}
.faq-question[aria-expanded="true"] .faq-icon {
  background: #111;
  border-color: #111;
  color: #fff;
}
.faq-question[aria-expanded="true"] .faq-icon-v {
  transform: scaleY(0);
  opacity: 0;
}
.faq-question[aria-expanded="true"] .faq-q-number {
  color: #111;
}

/* Answer */
.faq-answer {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
.faq-answer.is-open {
  grid-template-rows: 1fr;
}
.faq-answer-inner {
  overflow: hidden;
}
.faq-answer-inner p {
  margin: 0;
  padding-bottom: 24px;
  padding-left: 42px;
  font-size: 15px;
  line-height: 1.75;
  color: #666;
}

/* Mobile */
@media (max-width: 600px) {
  .collection-faq { padding: 48px 16px; }
  .faq-header { text-align: left; }
  .faq-q-number { display: none; }
  .faq-answer-inner p { padding-left: 0; }
  .faq-question { gap: 12px; }
}
</style>

<script>
(function () {
  var btns = document.querySelectorAll('#collection-faq .faq-question');
  btns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var isOpen = btn.getAttribute('aria-expanded') === 'true';
      var panel  = document.getElementById(btn.getAttribute('aria-controls'));

      // close all
      btns.forEach(function (b) {
        b.setAttribute('aria-expanded', 'false');
        var p = document.getElementById(b.getAttribute('aria-controls'));
        p.classList.remove('is-open');
      });

      // open clicked (if it was closed)
      if (!isOpen) {
        btn.setAttribute('aria-expanded', 'true');
        panel.classList.add('is-open');
      }
    });
  });
})();
</script>

{% endif %}
